-- 101: HSK 6 · шинэ хэлбэр (3.0) · Загвар №1 — өөрсдийн зохиосон загвар шалгалт.
-- 82 асуулт: сонсгол 40, уншлага 40, бичих 2. Аудио апп дотроо (/mock-tests/n6-01/). Дахин ажиллуулахад аюулгүй.
begin;

insert into public.mock_tests (id, hsk_level, title, total_questions, time_limit_min, has_writing, sections, is_active)
values ('N6-01', 6, 'HSK 6 · шинэ хэлбэр (3.0) · Загвар №1', 82, 112, true, '[{"skill": "listening", "audio_url": "/mock-tests/n6-01/listening.mp3", "time_min": 27, "parts": [{"desc": "Богино мэдээ → агуулгад тохирох өгүүлбэр", "part": 1, "range": [1, 8], "q_type": "choice"}, {"desc": "Өгүүлэл сонсоод асуултад хариулах", "part": 2, "range": [9, 28], "q_type": "choice"}, {"desc": "Ярилцлага сонсоод асуултад хариулах", "part": 3, "range": [29, 40], "q_type": "choice"}]}, {"skill": "reading", "audio_url": null, "time_min": 40, "parts": [{"desc": "Эхийн хоосон зайд үг сонгох", "part": 1, "range": [41, 50], "q_type": "choice"}, {"desc": "Эхийн хоосон зайд өгүүлбэр сонгох", "part": 2, "range": [51, 60], "q_type": "choice"}, {"desc": "Урт эх унших → асуултын хариу", "part": 3, "range": [61, 80], "q_type": "choice"}]}, {"skill": "writing", "audio_url": null, "time_min": 45, "parts": [{"desc": "Хэрэглээний бичвэр (150+ ханз)", "part": 1, "range": [81, 81], "q_type": "essay"}, {"desc": "Үзэл бодлын зохион бичлэг (300+ ханз)", "part": 2, "range": [82, 82], "q_type": "essay"}]}]'::jsonb, true)
on conflict (id) do update set hsk_level=excluded.hsk_level, title=excluded.title, total_questions=excluded.total_questions,
  time_limit_min=excluded.time_limit_min, has_writing=excluded.has_writing, sections=excluded.sections, is_active=excluded.is_active;

insert into public.mock_test_questions
  (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note)
values
  ('N6-01', 'listening', 1, 1, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "农村旅行费用很高"}, {"key": "B", "text": "年轻人喜欢周末去农村"}, {"key": "C", "text": "农民不欢迎城里人"}, {"key": "D", "text": "城市生活没有压力"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«越来越多的年轻人选择在周末去农村» — залуус амралтын өдөр хөдөө явах дуртай болсон. Зардал нь «不高».', 15.9, 39.6, '女：近年来，越来越多的年轻人选择在周末去农村住上一两天。他们白天帮农民摘水果，晚上围着火聊天儿。这种旅行方式花费不高，却能让人暂时远离城市的压力，因此很受欢迎。', '{"transcript": [{"zh": "女：近年来，越来越多的年轻人选择在周末去农村住上一两天。他们白天帮农民摘水果，晚上围着火聊天儿。这种旅行方式花费不高，却能让人暂时远离城市的压力，因此很受欢迎。"}], "why": "«越来越多的年轻人选择在周末去农村» — залуус амралтын өдөр хөдөө явах дуртай болсон. Зардал нь «不高»."}'::jsonb),
  ('N6-01', 'listening', 1, 2, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "步行有助于减轻焦虑"}, {"key": "B", "text": "开车的人工作效率更高"}, {"key": "C", "text": "调查对象都是学生"}, {"key": "D", "text": "走路时应该思考工作"}]'::jsonb, 'A', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«步行上下班的人…更少感到焦虑» — алхах нь түгшүүрийг бууруулдаг. Судалгаанд ажилчид (上班族) оролцсон.', 53.2, 71.3, '男：一项针对三千名上班族的调查显示，每天步行上下班的人，比开车的人更少感到焦虑。研究者认为，走路时人的注意力会从工作中转移出来，这相当于给大脑放了一个短假。', '{"transcript": [{"zh": "男：一项针对三千名上班族的调查显示，每天步行上下班的人，比开车的人更少感到焦虑。研究者认为，走路时人的注意力会从工作中转移出来，这相当于给大脑放了一个短假。"}], "why": "«步行上下班的人…更少感到焦虑» — алхах нь түгшүүрийг бууруулдаг. Судалгаанд ажилчид (上班族) оролцсон."}'::jsonb),
  ('N6-01', 'listening', 1, 3, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "博物馆周五不开放"}, {"key": "B", "text": "夜间参观需要另外收费"}, {"key": "C", "text": "观众数量低于预期"}, {"key": "D", "text": "夜间开放方便了上班族"}]'::jsonb, 'D', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«白天要上班的市民终于有机会来看展览了» — ажилтай хүмүүст боломж олгосон. Үзэгчийн тоо хүлээлтээс «远远超出».', 84.9, 102.4, '女：这家博物馆最近推出了“夜间开放”活动，每周五晚上延长开放到十点。白天要上班的市民终于有机会来看展览了，第一个周五就接待了五千多名观众，远远超出了博物馆的预期。', '{"transcript": [{"zh": "女：这家博物馆最近推出了“夜间开放”活动，每周五晚上延长开放到十点。白天要上班的市民终于有机会来看展览了，第一个周五就接待了五千多名观众，远远超出了博物馆的预期。"}], "why": "«白天要上班的市民终于有机会来看展览了» — ажилтай хүмүүст боломж олгосон. Үзэгчийн тоо хүлээлтээс «远远超出»."}'::jsonb),
  ('N6-01', 'listening', 1, 4, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "咖啡对睡眠没有任何影响"}, {"key": "B", "text": "咖啡的作用能持续一整天"}, {"key": "C", "text": "下午两点前喝咖啡影响不大"}, {"key": "D", "text": "专家建议大家不要喝咖啡"}]'::jsonb, 'C', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«只要在下午两点以前喝…并没有明显影响» — 14 цагаас өмнө уувал нөлөө бага.', 116.0, 135.5, '男：很多人认为喝咖啡会影响睡眠，其实这与喝咖啡的时间有关。专家指出，咖啡的作用一般持续六个小时左右，只要在下午两点以前喝，对大多数人的睡眠并没有明显影响。', '{"transcript": [{"zh": "男：很多人认为喝咖啡会影响睡眠，其实这与喝咖啡的时间有关。专家指出，咖啡的作用一般持续六个小时左右，只要在下午两点以前喝，对大多数人的睡眠并没有明显影响。"}], "why": "«只要在下午两点以前喝…并没有明显影响» — 14 цагаас өмнө уувал нөлөө бага."}'::jsonb),
  ('N6-01', 'listening', 1, 5, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "小份菜的价格和普通份一样"}, {"key": "B", "text": "学生们对小份菜不满意"}, {"key": "C", "text": "食堂的浪费现象明显减少"}, {"key": "D", "text": "食堂取消了普通份的菜"}]'::jsonb, 'C', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«倒掉的剩饭剩菜减少了近四成» — хаягдал бараг 40%-иар буурсан. «四成» = 40%.', 149.1, 167.4, '女：为了减少浪费，这所大学的食堂开始提供“小份菜”，价格是普通份的一半。实行一个月后，食堂每天倒掉的剩饭剩菜减少了近四成，学生们也表示，这样可以多尝几种菜。', '{"transcript": [{"zh": "女：为了减少浪费，这所大学的食堂开始提供“小份菜”，价格是普通份的一半。实行一个月后，食堂每天倒掉的剩饭剩菜减少了近四成，学生们也表示，这样可以多尝几种菜。"}], "why": "«倒掉的剩饭剩菜减少了近四成» — хаягдал бараг 40%-иар буурсан. «四成» = 40%."}'::jsonb),
  ('N6-01', 'listening', 1, 6, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "老人拍照是为了赚钱"}, {"key": "B", "text": "老人想记录正在消失的老房子"}, {"key": "C", "text": "老人年轻时就是摄影师"}, {"key": "D", "text": "老人只在自己的村子拍照"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«这些房子正在一座座消失，他想为后人留下一些记忆» — алга болж буй хуучин байшингуудыг баримтжуулах.', 181.0, 201.6, '男：这位七十岁的老人退休后爱上了摄影。十年来，他走遍了全省一百多个村子，拍下了两万多张老房子的照片。他说，这些房子正在一座座消失，他想为后人留下一些记忆。', '{"transcript": [{"zh": "男：这位七十岁的老人退休后爱上了摄影。十年来，他走遍了全省一百多个村子，拍下了两万多张老房子的照片。他说，这些房子正在一座座消失，他想为后人留下一些记忆。"}], "why": "«这些房子正在一座座消失，他想为后人留下一些记忆» — алга болж буй хуучин байшингуудыг баримтжуулах."}'::jsonb),
  ('N6-01', 'listening', 1, 7, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "屏幕阅读更有利于记忆"}, {"key": "B", "text": "孩子不喜欢纸书"}, {"key": "C", "text": "研究者反对使用电子产品"}, {"key": "D", "text": "纸书有助于记住细节"}]'::jsonb, 'D', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«阅读纸书时…更容易记住故事的细节» — цаасан ном нарийн ширийнийг тогтооход тустай.', 215.2, 233.8, '女：研究发现，孩子在阅读纸书时，比在屏幕上阅读更容易记住故事的细节。研究者解释说，翻书的动作和书的厚度能帮助大脑记住内容出现的位置，而屏幕上的文字缺少这样的帮助。', '{"transcript": [{"zh": "女：研究发现，孩子在阅读纸书时，比在屏幕上阅读更容易记住故事的细节。研究者解释说，翻书的动作和书的厚度能帮助大脑记住内容出现的位置，而屏幕上的文字缺少这样的帮助。"}], "why": "«阅读纸书时…更容易记住故事的细节» — цаасан ном нарийн ширийнийг тогтооход тустай."}'::jsonb),
  ('N6-01', 'listening', 1, 8, 'choice', 'Сонссон агуулгатай тохирох өгүүлбэрийг сонго.', '[{"key": "A", "text": "骑车上班的人明显增多了"}, {"key": "B", "text": "城市的地铁停止运行了"}, {"key": "C", "text": "堵车情况比以前更严重"}, {"key": "D", "text": "自行车道只有三十公里"}]'::jsonb, 'A', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.short_news']::text[], '«骑车上班的人数比两年前增加了一倍» — дугуйгаар ажилдаа явагчид хоёр дахин нэмэгдсэн. Түгжрэл «有所缓解» (багассан).', 247.4, 266.6, '男：这座城市去年新建了三百公里的自行车专用道，并且在地铁站附近设置了大量停车点。如今，骑车上班的人数比两年前增加了一倍，早晚高峰的堵车情况也有所缓解。', '{"transcript": [{"zh": "男：这座城市去年新建了三百公里的自行车专用道，并且在地铁站附近设置了大量停车点。如今，骑车上班的人数比两年前增加了一倍，早晚高峰的堵车情况也有所缓解。"}], "why": "«骑车上班的人数比两年前增加了一倍» — дугуйгаар ажилдаа явагчид хоёр дахин нэмэгдсэн. Түгжрэл «有所缓解» (багассан)."}'::jsonb),
  ('N6-01', 'listening', 2, 9, 'choice', '', '[{"key": "A", "text": "语文和数学"}, {"key": "B", "text": "兴趣类课程"}, {"key": "C", "text": "职业资格考试"}, {"key": "D", "text": "外语"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.passage']::text[], '«教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器» — сонирхлын хичээлүүд.', 292.8, 360.0, '女：说起“夜校”，很多人会想到上个世纪工人下班后学文化的地方。然而最近，夜校在年轻人中间重新流行起来。与过去不同，现在的夜校教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器等课程。上课时间一般安排在工作日晚上七点到九点，每门课十二次，费用只要五百元左右，比社会上的培训班便宜得多。夜校为什么这么受欢迎？一位学员说，白天的工作让她感到疲劳，而晚上的两个小时完全属于自己，学到一种技能的同时，还能认识一些有共同爱好的朋友。专家认为，夜校的流行反映出年轻人对精神生活的追求：他们不再满足于下班后看手机，而是希望通过学习让生活变得更加丰富。
问：现在的夜校主要教什么？', '{"transcript": [{"zh": "女：说起“夜校”，很多人会想到上个世纪工人下班后学文化的地方。然而最近，夜校在年轻人中间重新流行起来。与过去不同，现在的夜校教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器等课程。上课时间一般安排在工作日晚上七点到九点，每门课十二次，费用只要五百元左右，比社会上的培训班便宜得多。夜校为什么这么受欢迎？一位学员说，白天的工作让她感到疲劳，而晚上的两个小时完全属于自己，学到一种技能的同时，还能认识一些有共同爱好的朋友。专家认为，夜校的流行反映出年轻人对精神生活的追求：他们不再满足于下班后看手机，而是希望通过学习让生活变得更加丰富。"}, {"zh": "问：现在的夜校主要教什么？"}], "why": "«教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器» — сонирхлын хичээлүүд."}'::jsonb),
  ('N6-01', 'listening', 2, 10, 'choice', '', '[{"key": "A", "text": "周末全天上课"}, {"key": "B", "text": "每门课上一年"}, {"key": "C", "text": "费用比较低"}, {"key": "D", "text": "只招收工人"}]'::jsonb, 'C', 'auto', 1, '/mock-tests/n6-01/listening.mp3', null, false, array['sk.listening.passage']::text[], '«费用只要五百元左右，比…培训班便宜得多» — төлбөр хямд.', 292.8, 378.9, '女：说起“夜校”，很多人会想到上个世纪工人下班后学文化的地方。然而最近，夜校在年轻人中间重新流行起来。与过去不同，现在的夜校教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器等课程。上课时间一般安排在工作日晚上七点到九点，每门课十二次，费用只要五百元左右，比社会上的培训班便宜得多。夜校为什么这么受欢迎？一位学员说，白天的工作让她感到疲劳，而晚上的两个小时完全属于自己，学到一种技能的同时，还能认识一些有共同爱好的朋友。专家认为，夜校的流行反映出年轻人对精神生活的追求：他们不再满足于下班后看手机，而是希望通过学习让生活变得更加丰富。
问：关于夜校的课程，可以知道什么？', '{"transcript": [{"zh": "女：说起“夜校”，很多人会想到上个世纪工人下班后学文化的地方。然而最近，夜校在年轻人中间重新流行起来。与过去不同，现在的夜校教的不是语文、数学，而是画画儿、摄影、做蛋糕、乐器等课程。上课时间一般安排在工作日晚上七点到九点，每门课十二次，费用只要五百元左右，比社会上的培训班便宜得多。夜校为什么这么受欢迎？一位学员说，白天的工作让她感到疲劳，而晚上的两个小时完全属于自己，学到一种技能的同时，还能认识一些有共同爱好的朋友。专家认为，夜校的流行反映出年轻人对精神生活的追求：他们不再满足于下班后看手机，而是希望通过学习让生活变得更加丰富。"}, {"zh": "问：关于夜校的课程，可以知道什么？"}], "why": "«费用只要五百元左右，比…培训班便宜得多» — төлбөр хямд."}'::jsonb),
